"""Islamiat (Ikhtiari) XII PDF66: pp.122–123 — ahadith 29 (end), 30, 31. Run: python class12_iski_page066.py"""
from class12_iski_common import BOOK, Builder, rec, P, L, AR


def p66():
    b = Builder()
    P(b, [('… will remove the fire. Stopping backbiting is obligatory, firstly because helping one another is obligatory on every Muslim. The Messenger of Allah ﷺ said: "A Muslim is the brother of a Muslim; he neither wrongs him nor abandons helping him." (Bukhari)', 'سے آگ کو دور کر دے گا۔ غیبت سے روکنا ایک تو اس لیے فرض ہے کہ ایک مسلمان پر دوسرے کی مدد فرض ہے۔ رسول اللہ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا ”مسلمان، مسلمان کا بھائی ہے نہ اس پر ظلم کرتا ہے نہ اس کی مدد چھوڑتا ہے“۔ (بخاری)', '… اور لرې کړي. له غیبت منع کول یو خو ځکه فرض دي چې پر مسلمان د بل مرسته فرض ده. د الله رسول ﷺ وفرمایل: «مسلمان د مسلمان ورور دی؛ نه پرې ظلم کوي او نه یې مرسته پرېږدي.» (بخاري)'),
          ('Secondly, because forbidding evil is obligatory on every Muslim according to his capacity. The Noble Messenger ﷺ said: "Whoever among you sees an evil, let him stop it with his hand; if he does not have this strength, then with his tongue; if he does not have even this strength, then with his heart — and this is the weakest degree of faith." (Muslim)', 'دوسرا اس لیے کہ برائی سے منع کرنا ہر مسلمان پر بقدرِ استطاعت فرض ہے۔ رسول کریم صلی اللہ علیہ وآلہٖ وسلم نے فرمایا ”تم میں سے جو برائی دیکھے تو اسے ہاتھ سے روکے اگر یہ طاقت نہ رکھے تو زبان سے، اگر یہ بھی طاقت نہ رکھے تو دل سے اور یہ ایمان کا کمزور درجہ ہے۔“ (مسلم)', 'دویم ځکه چې له بدۍ منع کول پر هر مسلمان د وس په اندازه فرض دي. رسول کریم ﷺ وفرمایل: «ستاسو څوک چې بدي وویني، په لاس دې یې منع کړي؛ که دا توان ونه لري، نو په ژبه؛ که دا توان هم ونه لري، نو په زړه — او دا د ایمان کمزورې درجه ده.» (مسلم)'),
          ('(2) If one cannot stop the backbiting, what should one do: In a gathering where the commands of Allah the Exalted are being violated and they are being mocked, then the person sitting in that gathering too will be like them. The saying of the Exalted Creator is: "And indeed Allah has sent down this command upon you in the Book, that when you hear that the verses of Allah are being denied and mocked, then as long as those people do not engage in other talk, do not sit near them, otherwise you too will be counted like them. There is no doubt that Allah is going to gather the hypocrites and the disbelievers in Hell." (An-Nisa: 140)', '(۲) اگر غیبت سے نہ روک سکے تو کیا کرے: جس مجلس میں اللہ تعالیٰ کے احکام کی خلاف ورزی ہو رہی ہو اور اُن کا مذاق اُڑایا جا رہا ہو تو اُس مجلس میں بیٹھنے والا شخص بھی اُن کی طرح ہوگا۔ ارشادِ باری تعالیٰ ہے: ”اور یقیناً اللہ نے تم پر کتاب میں یہ حکم نازل فرمایا ہے کہ جب تم اللہ کی آیات کے متعلق سنو کہ ان سے انکار کیا جا رہا ہے اور ان کی ہنسی اُڑائی جا رہی ہے تو جب تک وہ لوگ اور باتیں نہ کرنے لگیں ان کے پاس مت بیٹھو، ورنہ تم بھی انہیں جیسے شمار ہو گے۔ کچھ شک نہیں کہ اللہ منافقوں اور کافروں کو دوزخ میں اکھٹا کرنے والا ہے۔“ (النساء: ۱۴۰)', '(۲) که له غیبت منع نشي کړای، نو څه وکړي: په کومه غونډه کې چې د الله تعالی د احکامو سرغړونه کېږي او ملنډې پرې وهل کېږي، په هغه غونډه کې ناست کس به هم د هغوی په څېر وي. د الله تعالی ارشاد دی: «او بې‌شکه الله په کتاب کې پر تاسو دا حکم نازل کړی چې کله واورئ چې د الله له آیتونو انکار کېږي او ملنډې پرې وهل کېږي، نو تر څو چې هغه خلک په نورو خبرو بوخت نشي، له هغوی سره مه کېنئ، ګنې تاسو به هم د هغوی په څېر وشمېرل شئ. هېڅ شک نشته چې الله منافقان او کافران په دوزخ کې راټولوونکی دی.» (النساء: ۱۴۰)')])
    b.h('Hadith no. 30', 'حدیث نمبر 30', 'حدیث نمبر ۳۰')
    AR(b, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللّٰهُ عَنْهُ قَالَ لَقِيْتُ رَسُوْلَ اللّٰهِ عَلَيْهِ السَّلَامُ يَوْمًا فَقُلْتُ يَا رَسُوْلَ اللّٰهِ مَا النَّجَاةُ؟ فَقَالَ: يَا عُقْبَةُ اَمْلِكْ عَلَيْكَ لِسَانَكَ وَلْيَسَعْكَ بَيْتُكَ وَابْكِ عَلٰى خَطِيْئَتِكَ', 'سنن الترمذی کتاب الذھد: حدیث نمبر ۲۴۰۶')
    b.p('Translation: It is narrated from Uqbah bin Amir that one day I met the Messenger of Allah ﷺ and asked him what salvation is. He ﷺ said: O Uqbah, keep your tongue under control, stay in your house, and weep over your faults.', 'ترجمہ: عقبہ بن عامر سے روایت ہے کہ میں ایک دن رسول اللہ صلی اللہ علیہ وآلہٖ وسلم سے ملا اور ان سے پوچھا کہ نجات کیا ہے۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا اے عقبہ اپنی زبان کو قابو میں رکھو اور اپنے گھر ٹھہرے رہو اور اپنی خطاؤں پر روؤ۔', 'ژباړه: له عقبه بن عامر روایت دی چې یوه ورځ زه د الله له رسول ﷺ سره ولیدل او ومې پوښتل چې نجات څه دی؟ هغه ﷺ وفرمایل: اې عقبه، خپله ژبه په واک کې وساته، په خپل کور کې پاتې شه، او پر خپلو خطاګانو وژاړه.')
    b.h('Explanation', 'تشریح', 'تشریح')
    b.p('In this blessed hadith the practical wisdom regarding attaining salvation has been told. For attaining salvation and safety …', 'اس حدیثِ مبارکہ میں نجات حاصل کرنے کے بارے میں حکمتِ عملی بتائی گئی ہے۔ نجات اور سلامتی حاصل', 'په دې مبارک حدیث کې د نجات د ترلاسه کولو په اړه عملي حکمت ښوول شوی. د نجات او سلامتۍ د ترلاسه کولو …')
    r1 = rec(b, 2, 122, 66, [122])
    t = Builder()
    t.p('… three things have been prescribed.', 'کرنے کے لیے تین چیزیں ارشاد فرمائی گئی ہیں۔', '… لپاره درې شیان ارشاد شوي.')
    L(t, [('1. Keeping the tongue under control', '۱۔ زبان پر قابو رکھنا', '۱. پر ژبه واک ساتل'),
          ('2. Staying at home (reforming the household)', '۲۔ گھر میں رکے رہنا (گھر والوں کی اصلاح کرنا)', '۲. په کور کې پاتې کېدل (د کورنۍ اصلاح)'),
          ('3. Weeping over sins.', '۳۔ گناہوں پر رونا۔', '۳. پر ګناهونو ژړل.')])
    P(t, [('In daily routines countless quarrels and disorders arise only from wrong words that come out of the tongue. That is why it comes in a hadith that there is safety in silence; that is, one should say a good thing, otherwise one should remain silent. The principle "first think, then speak" is called better for this very reason, so that no such thing comes out of the mouth from which unpleasantness of any kind may arise.', 'روزمرہ معمولات میں بے شمار جھگڑے اور فساد زبان سے نکلے ہوئے غلط الفاظ سے ہی ہوتے ہیں۔ اسی لیے ایک حدیث میں آتا ہے کہ خاموشی میں سلامتی ہے۔ یعنی اچھی بات کہنی چاہیے ورنہ خاموش رہنا چاہیے۔ پہلے سوچو اور پھر بولو کا اصول اسی لیے بہتر بتایا جاتا ہے کہ منہ سے کوئی ایسی بات نہ نکل جائے جس سے کسی قسم کی بدمزگی ہو جائے۔', 'په ورځنیو معمولاتو کې بې‌شمېره شخړې او فسادونه یوازې له ژبې له وتلو ناسمو الفاظو پیدا کېږي. له همدې امله په یوه حدیث کې راغلي چې په چوپتیا کې سلامتي ده؛ یعنې ښه خبره باید وویل شي، ګنې چوپ پاتې کېدل پکار دي. د «لومړی فکر وکړه بیا خبرې وکړه» اصل ځکه غوره ښوول کېږي چې له خولې داسې خبره ونه وځي چې هر ډول ترخه‌والی ترې پیدا شي.'),
          ('By staying at home, or running towards home, is meant that from unnecessary wandering many evils are born. Staying at home and spending time with the household, being of use to them, and moreover giving them good upbringing, is a matter of good fortune. At the end it has been said that a person commits many sins knowingly or unknowingly. By shedding tears of remorse over them, seeking forgiveness, and repenting in the court of Allah the Exalted, a person will obtain salvation, and in this way he will also refrain from committing further sins.', 'گھر میں رکے رہنا یا گھر کی طرف دوڑنا سے مراد ہے کہ غیر ضروری آوارہ گردی سے کئی قباحتیں جنم لیتی ہیں۔ گھر میں رہ کر اہلِ خانہ کے ساتھ وقت گزارنا اور ان کے کام آنا نیز ان کی اچھی تربیت کرنا سعادت مندی کی بات ہوتی ہے۔ آخر میں فرمایا گیا ہے کہ انسان سے دانستہ یا نادانستہ کئی گناہ سرزد ہو جاتے ہیں۔ ان پر ندامت کے آنسو بہانا، مغفرت طلب کرنا اور اللہ تعالیٰ کی بارگاہ میں توبہ کرنے سے انسان کو نجات مل جائے گی۔ اور اس طرح وہ مزید گناہ کرنے سے بھی باز آ جائے گا۔', 'په کور کې پاتې کېدو یا کور ته د منډې وهلو مطلب دا دی چې له غیرضروري ګرځېدو ډېرې ناوړتیاوې زېږي. په کور کې پاتې کېدل او له کورنۍ سره وخت تېرول، د هغوی په کار راتلل، او د هغوی ښه روزنه د سعادت خبره ده. په پای کې ویل شوي چې له انسان څخه په پوهه یا ناپوهۍ ډېرې ګناوې کېږي. پر هغو د ندامت اوښکې تویول، بښنه غوښتل او د الله تعالی دربار ته توبه ایستل انسان ته نجات ورکوي، او په دې ډول به له نورو ګناهونو هم لاس واخلي.')])
    t.h('Hadith no. 31', 'حدیث نمبر 31', 'حدیث نمبر ۳۱')
    AR(t, 'عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللّٰهُ عَنْهُ اَنَّهٗ قِيْلَ يَا رَسُوْلَ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ مَا الْغِيْبَةُ؟ قَالَ: ذِكْرُكَ اَخَاكَ بِمَا يَكْرَهُ قِيْلَ اَفَرَاَيْتَ اِنْ كَانَ فِيْ اَخِيْ مَا اَقُوْلُ؟ قَالَ اِنْ كَانَ فِيْهِ مَا تَقُوْلُ فَقَدِ اغْتَبْتَهٗ وَاِنْ لَّمْ يَكُنْ فِيْهِ مَا تَقُوْلُ فَقَدْ بَهَتَّهٗ', 'سنن ابی داؤد کتاب الادب باب فی الغیبۃ۔ حدیث ۴۸۷۴')
    t.p('Translation: Hazrat Abu Hurayrah (may Allah be pleased with them) asked the Messenger of Allah ﷺ what backbiting is. He ﷺ said: to mention such a thing of your brother which he dislikes. Then he asked: if that thing which I say is present in him? He ﷺ said: if what you say is present in him, then you backbit him; and if it is not present in him, then you slandered him.', 'ترجمہ: حضرت ابوہریرہ رضی اللہ عنہما نے رسول اللہ صلی اللہ علیہ وآلہٖ وسلم سے پوچھا کہ غیبت کیا ہے؟ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ اپنے بھائی کی ایسی بات کا ذکر کرنا جسے وہ ناپسند کرے۔ پھر پوچھا! اگر وہ بات جو میں کہتا ہوں وہ اس میں موجود ہو تو؟ آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا۔ اگر جو تو کہتا ہے وہ اس میں موجود ہے تو، تو نے اس کی غیبت کی اور اگر اُس میں موجود نہیں ہے تو، تو نے اس پر بہتان لگایا۔', 'ژباړه: حضرت ابوهریره رضي الله عنه له الله له رسول ﷺ وپوښتل چې غیبت څه دی؟ هغه ﷺ وفرمایل: د خپل ورور د داسې خبرې یادول چې هغه یې نه خوښوي. بیا یې وپوښتل: که هغه خبره چې زه یې وایم په هغه کې موجوده وي؟ هغه ﷺ وفرمایل: که څه چې ته وایې په هغه کې موجود دي، نو تا یې غیبت وکړ؛ او که په هغه کې نه وي، نو تا پرې تهمت ولګاوه.')
    BOOK.save(66, [(2, r1), (2, rec(t, 2, 123, 66, [123]))], issues=[{'id': 'iski12-pdf066', 'unit': 2, 'printedPage': 122,
               'description': 'p.123 translation prints "حضرت ابوہریرہ رضی اللہ عنہما" (dual form for one Companion) — kept as printed. Hadith 30 Arabic prints "رَسُوْلَ اللّٰهِ عَلَيْهِ السَّلَامُ" and reference "کتاب الذھد" — kept as printed. Student marks on p.123 excluded.'}])


if __name__ == '__main__':
    p66()
